quests[54391] = { id = 54391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Spiegelnder Goldberyll", description = "Gutes, herzhaftes Fleisch ist genau die Nahrung, die unsere Verbündeten verdienen, bevor sie in die Schlacht ziehen. Außerdem lässt sich damit ein zünftiger Eintopf zubereiten, genau wie ihn unsere Truppen lieben, wenn die Winde gut stehen und die Nächte kälter werden.\n\nWenn Ihr mir ein paar frische gewürzte Lenden besorgt, bringe ich sie gerne zu unseren Versorgungsoffizieren.", sourceObjective = "Sammelt 20 gewürzte Lenden für Senedras im Hafen von Boralus.", progress = "Verstärkungsedelsteine sind enorm wichtig. Wenn wir den Kampf überstehen wollen, müssen wir vorbereitet sein.", completion = "Die sollten ausreichen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54392] = { id = 54392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Sandschleicher", description = "In Zeiten wie diesen ist es wichtig, dass man stets kampfbereit ist. Unsere Tiere mit passenden Steigbügeln auszustatten, ist schon ein Schritt in die richtige Richtung.\n\nAlso bringt mir ein paar, und wir werden sie gut zu nutzen wissen.", sourceObjective = "Sammelt 30 monelitgehärtete Steigbügel für Brandal Dunkelbart im Hafen von Boralus.", progress = "Unsere Nahrungsvorräte sind ziemlich zusammengeschrumpft. Besonders unsere Vorräte an Fisch. Ihr seid nicht zufällig ein Meisterangler?", completion = "Jawoll, das sollte reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54393] = { id = 54393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Scharlachdiamant", description = "Ein Kampf wird nicht dadurch entschieden, welche Seite die beste Rüstung oder die schärfsten Klingen hat, aber helfen tun sie allemal! Fest steht, dass nicht nur unsere Verbündeten Unterstützung brauchen, sondern auch unsere Kampfbegleiter.\n\nWenn Ihr also zusätzliche Hufplatten für unsere tapferen Tiere zur Verfügung stellen könnt, sorgen unsere Hufschmiede für den Rest.", sourceObjective = "Sammelt 20 monelitgehärtete Hufplatten für Brandal Dunkelbart im Hafen von Boralus.", progress = "Unsere eigenen Juwelenschleifer sind schwer damit beschäftigt, unsere Rüstungen mit ihren geschliffenen Steinen zu bestücken.\n\nUnser Vorrat an ungeschliffenen Edelsteinen ist aber bedenklich niedrig. Habt Ihr vielleicht welche abzugeben?", completion = "Sehr großzügig von Euch, {name}. Die werden wir bestimmt gut gebrauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[54394] = { id = 54394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Zähe Lende", description = "Eine unserer letzten Lieferungen Alchemievorräte wurde auf dem Weg zum Lagerhaus abgefangen. Wir geben uns alle Mühe, unsere Lagerbestände wieder aufzufüllen, aber ich befürchte, wir werden unser Soll nicht erreichen.\n\nIhr wisst nicht zufällig, wo man zusätzliche Manatränke auftreiben könnte, oder?", sourceObjective = "Bringt 30 Manatränke der Küste zu Klara Strand im Hafen von Boralus.", progress = "Unsere Nahrungsvorräte gehen zur Neige, weil wir so viele Münder stopfen müssen. Habt Ihr irgendwelche Vorräte übrig?", completion = "Genau so etwas habe ich gesucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[54395] = { id = 54395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Würziges Steak mit Kartoffeln", description = "Man hat mir berichtet, dass unsere Verbündeten noch ein paar weitere Vorräte für die bevorstehende Schlacht beiseiteschaffen wollen. Wenn Euch ein paar Heiltränke der Küste unterkommen, würde ich sie nur zu gerne einlagern.", sourceObjective = "Sammelt 40 Heiltränke der Küste für Klara Strand im Hafen von Boralus.", progress = "Eine herzhafte Mahlzeit ist genau die Nahrung, die unsere Verbündeten verdienen.\n\nWenn Ihr mir ein paar frische würzige Steaks mit Kartoffeln besorgt, bringe ich sie gerne zu unseren Versorgungsoffizieren.", completion = "Hmm...\n\n<Senedras schnuppert genüsslich an dem Essen, das Ihr mitgebracht habt.>\n\nDas duftet einfach köstlich. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54396] = { id = 54396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Wildbeerenbrot", sourceObjective = "Bringt 40 Stahlhauttränke zu Klara Strand im Hafen von Boralus.", progress = "Habt Ihr schon von diesem neuen Nachtisch gehört, den die Köche zubereiten? Ich glaube, er nennt sich \"Wildbeerenbrot\". Ihr habt nicht zufällig welches dabei?", completion = "Danke, dass Ihr uns gleich so viel gebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54402] = { id = 54402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Bewegung", description = "{name}! Die Allianz hat erneut um Gnomeregans Stärke gebeten.\n\nHauptmann Funkdüse bittet um Eure fachkundige Unterstützung in dieser Angelegenheit.\n\nEr erwartet Euch in Neu-Tüftlerstadt, außerhalb von Gnomeregan.", sourceObjective = "Sucht Hauptmann Tret Funkdüse in Neu-Tüftlerstadt auf.", completion = "Der Rest der Gnome, die ich angefordert habe, sind kurz vor Euch eingetroffen. Gestattet mir, Euch die Situation zu erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[54403] = { id = 54403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezeitenweise Clarissa" }
quests[54404] = { id = 54404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenumtriebe", description = "Wir haben zusätzliche Unterstützung für unseren Plan, die Horde zu täuschen und das Bluttor anzugreifen, doch wir brauchen Eure Hilfe.\n\nDie Dunkeleisenzwerge haben einige Maulwurfmaschinen, die nur darauf warten, aus dem Boden hervorzubrechen, um frische Truppen zu bringen.\n\nWir haben verschiedene Punkte in Zalamar ausgemacht, die für diesen Zweck perfekt wären.\n\nNehmt dieses Gerät und stellt es in den folgenden Bereichen auf. Es wird den Dunkeleisenzwergen eine Nachricht senden, dort durchzubrechen.\n\nSie können in ihren Maschinen bleiben und sind dort sicher, bis unsere Armee eintrifft.", sourceObjective = "Markiert 3 Gebiete in Zalamar, damit die Maulwurfmaschinen dort auftauchen.", completion = "Ausgezeichnet! Wir sind der Auslöschung der Horde wieder einen Schritt nähergekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54407] = { id = 54407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauern im Sumpf", description = "Wir haben Zalamar und wir haben unseren Nebel. Jetzt müssen wir unseren Angriff auf die Horde richten.\n\nUnser Ziel ist es, so viel Land wie möglich in Nazmir einzunehmen, sodass die Horde glaubt, unsere Hauptflotte wäre hier.\n\nDas erste Ziel sind die Ruinen von Zul'jan, einer der Hauptstützpunkte der Horde in Nazmir.\n\nWir müssen uns einen Weg durch die Sümpfe zu unserer Angriffsposition bahnen. Trefft uns dort.", sourceObjective = "Trefft Euch mit Jaina Prachtmeer vor den Ruinen von Zul'jan.", completion = "Wir haben es geschafft und besitzen immer noch das Überraschungsmoment.", sourceObjectiveStatus = "unverified-source-field" }
quests[54412] = { id = 54412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regenguss von Zul'jan", description = "Jenseits des Nebels liegen die Ruinen von Zul'jan, einer der größten Außenposten der Horde in Nazmir. Wir müssen ihn übernehmen, damit unsere Streitkräfte weiter vorrücken können.\n\nDie Horde muss glauben, dass sich hier eine große Armee der Allianz befindet, also werden wir alles, was wir haben, in die Waagschale werfen, um die Ruinen zu erobern.\n\nUnsere Armee wird einen Sturmangriff beginnen und Ihr schließt Euch mit meinem Wasserelementar an.\n\nTrefft mich außerhalb der Ruinen, wenn Ihr fertig seid. Wir müssen weiter vorrücken.", sourceObjective = "Benutzt Jainas Wasserelementar, um die Ruinen von Zul'jan zu räumen.", completion = "Gute Arbeit, unsere Streitkräfte haben die Ruinen von Zul'jan eingenommen. Wir sind fast an unserem Bestimmungsort angelangt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54414] = { id = 54414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windesunruh" }
quests[54415] = { id = 54415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulpera für einen Tag" }
quests[54416] = { id = 54416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen für die Kriegsfront", description = "Wir müssen unsere Vorbereitungen treffen. \n\nKehrt sofort nach Zandalar zurück und ruft unsere Truppen zusammen. Alles, was unserer Sache dienlich ist, muss gespendet werden.\n\nGeht. Wir werden die Stellung halten.", sourceObjective = "Nehmt das Portal zurück zum Hafen von Zandalar, um Euch auf die Schlacht um die Dunkelküste vorzubereiten.", completion = "Willkommen zurück in Zuldazar. Wir werden an Eurer Seite sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[54417] = { id = 54417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtdemonstration", description = "Das Bluttor in Zandalar ist in unserer Reichweite. Sobald wir es eingenommen haben, werden die Horde und die Zandalari glauben, dass unsere große Invasion begonnen hat.\n\nUnsere Truppen kämpfen bereits gegen die Zandalari im Gefallenen Außenposten. Wir brauchen Eure Hilfe, um sie zurückzudrängen.\n\nIch werde mich darauf konzentrieren, das, was von der Horde und den Zandalari in den Ruinen von Zul'jan noch übrig ist, auszulöschen.", sourceObjective = "Besiegt 12 Zandalaritruppen im Gefallenen Außenposten.", completion = "Wir haben die Ruinen von Zul'jan eingenommen, und mit Eurer Hilfe wird unsere Armee die restlichen Zandalari hier auslöschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54418] = { id = 54418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mechaoberdampfhammer", description = "Uns liegen Berichte über eine Goblinmaschine vor, die verheerende Schäden bei unseren Truppen weiter vorne anrichtet. Sie nennen sie den A.M.O.D.\n\nIm Vergleich zu dem, was die Lichtgeschmiedeten an Bord der Vindikaar haben, ist das eine primitive Maschine.\n\nWir werden gemeinsam diese Maschine zu Fall bringen. Geht, ich werde in der Nähe der Maschine auf Euch warten und mich in den Kampf stürzen, wenn Ihr bereit seid.", sourceObjective = "Besiegt den A.M.O.D.", completion = "Ihr habt gut gekämpft! Es ist schade, dass wir uns bald trennen müssen. Ich hätte gern noch etwas länger an Eurer Seite gekämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54419] = { id = 54419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeskalation", description = "Eine von mein'n Rastari hat die Arbeiter un' Wachen auf'm Zocalo aufgewiegelt.\n\nMit ihren Dummheiten bedroh'n sie die Stabilität unsres Reiches. Wenn sie wütend sin', kann man drüber red'n, aber mutwillige Zerstörung könn'n wir nich' tolerier'n.\n\nBegebt Euch zum Markt vom Zocalo un' sorgt dort für Ruhe. Wie Ihr das macht, überlass ich Euch.\n\nIch will nur ein Ergebnis un' das is' Frieden, damit Talanji endlich gekrönt werd'n kann.", sourceObjective = "Bezwingt 12 Aufständische auf dem Zocalo.", completion = "Ich hoff, wir sind nich' zu spät, um diese Unruhen zu unterbind'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54421] = { id = 54421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Bestien zähmen", description = "Unser Ziel ist es, das Bluttor anzugreifen, aber um ehrlich zu sein, haben wir nicht die nötigen Streitkräfte.\n\nAus dem Grund haben wir Gnomtechnologie. Die Zandalari haben Kampfbestien, Terrorhörner mit mächtigen Waffen.\n\nEinige dieser Tiere ruhen sich im Gefallenen Außenposten aus. Dieses Gerät, der Rediskombobulator, wird uns Kontrolle über diese Tiere verschaffen. \n\nNehmt dieses Gerät und wendet es auf diese Schlachtbestien an. Wir werden das Bluttor angreifen, sobald wir sie unter Kontrolle haben.", sourceObjective = "Benutzt den Rediskombobulator, um 3 Schlachtbestien zu kontrollieren.", completion = "Gute Arbeite, diese Bestien werden bei der Übernahme des Bluttors unbedingt erforderlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[54424] = { id = 54424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zwielichtige Gestalt", description = "Eure Anhänger sprechen von einem Schmuggler mit Witz und Verstand, der sie mit Geschichten von weit entfernten Ländern verzaubern konnte.\n\nObwohl es ein beträchtliches Sümmchen kostete, konnten sie ein Abzeichen erwerben. Wenn man dieses dem Schmuggler vorlegt, darf man Waren von ihm kaufen.", sourceObjective = "Bringt das Abzeichen zu der zwielichtigen Gestalt unter der Brücke.", progress = "Glaubt Ihr wirklich, Ihr solltet mit mir sprechen?", completion = "Also schön, es scheint, als ob Ihr in Ordnung seid.\n\nJa, ich habe Haustiere, aber an die kommt man nicht so einfach ran, also erwartet nicht, dass ich sie verschenke.", sourceObjectiveStatus = "unverified-source-field" }
quests[54433] = { id = 54433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von Azshara", description = "Das sind Befehle auf diesem Medaillon. Den Naga wurde befohlen, über unsere Küsten herzufallen und nach mächtigen Artefakten zu suchen.\n\n<Kojo schaut Euch nachdenklich an.>\n\nIch hörte Geschichten über einen Priester, der mit einem schrecklichen Dolch gegen die Brennende Legion gekämpft haben soll. Es heißt, dass die Klinge... Xal'atath... von den Geheimnissen der Tiefe flüstert. Das könnte unsere beste Gelegenheit sein, um herauszufinden, wonach die Naga suchen.\n\nIch habe vor Kurzem einen behelfsmäßigen Altar der Naga in Atal'Gral entdeckt. Wenn Ihr Xal'atath dort hinbringt, wird der Dolch vielleicht wertvolle Informationen preisgeben.", sourceObjective = "Nehmt Xal'atath und findet den behelfsmäßigen Altar.", completion = "<Ihr verspürt ein bekanntes Gefühl, als Xal'atath mit Eurem Geist in Kontakt tritt.\n\nEine faszinierende Mischung aus Schrecken und... Entzücken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54434] = { id = 54434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerenmeister Schattenfall" }
quests[54436] = { id = 54436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Irrwische sind, fallen Späne", description = "Es läuft gut an, aber wir brauchen mehr Holz, wenn wir diese Schlacht gewinnen wollen.\n\nDie Horde hat ein Sägewerk im Norden von Bashal'Aran hinter dem Verlorenen Wegekreuz gebaut. Wenn wir das einnehmen, verhindern wir die weitere Zerstörung des Waldes und gewinnen die Irrwische als zusätzliche Helfer.\n\nZwei Fliegen mit einer Klappe!", sourceObjective = "Nehmt die Glutfalllichtung ein und bringt die Irrwische dazu, Euch zu helfen.", completion = "Diese Irrwische werden uns eine große Hilfe sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[54437] = { id = 54437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Owynn Graddock" }
quests[54438] = { id = 54438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tiegel der Stürme: Relikte des Schattens", description = "Euer Vorhaben, die Naga aufzuhalten, war eine edle Absicht, {name}. Aber der finstere Dolch hat Euch dazu verleitet, einem großen Feind ein paar sehr mächtige Relikte zu liefern.\n\nDiese Artefakte werden mit Sicherheit sehr gut bewacht. Sammelt Eure Verbündeten, {class}, und kehrt dann zum Tiegel der Stürme zurück.\n\nSchaltet alle Gegner aus, die Euch im Wege sind. Sorgt dafür, dass diese Relikte nicht gegen die Allianz eingesetzt werden können.\n\nDie Naga dürfen auf keinen Fall ihren Sturm heraufbeschwören... oder noch etwas viel Schlimmeres.", sourceObjective = "Haltet Uu'nat im Tiegel der Stürme auf.", completion = "Ich freue mich, dass Ihr die Vasallen von N'Zoth besiegen konntet, {name}. Aber ich fühle tief in mir, dass die Gefahr noch längst nicht vorbei ist.\n\nBleibt auf der Hut, Champion. Wer den Blick eines Alten Gottes auf sich zieht, dem stehen finstere Zeiten bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[54439] = { id = 54439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tiegel der Stürme: Relikte des Schattens", description = "Euer Vorhaben, die Naga aufzuhalt'n, war 'ne edle Absicht, {name}. Aber der sprechende Dolch hat Euch dazu verleitet, unsren Feinden ein paar sehr mächtige Relikte zu liefern.\n\nDiese Artefakte werd'n mit Sicherheit sehr gut bewacht. Sammelt Eure Verbündeten, {class}, und kehrt dann zum Tiegel der Stürme zurück.\n\nSchaltet alle Gegner aus, die Euch im Weg sind. Sorgt dafür, dass diese Relikte nich' gegen die Horde eingesetzt werden könn'n.\n\nUnd wenn Euch in Zukunft irgend'ne finstre Waffe um 'nen Gefallen bittet... dann lehnt besser ab.", sourceObjective = "Haltet Uu'nat im Tiegel der Stürme auf.", completion = "Ich freu mich, dass Ihr die Vasallen von N'Zoth besiegen konntet, {name}. Aber irgendwas sagt mir, dass die Gefahr noch längst nich' vorbei is'.\n\nBleibt auf der Hut, Champion. Ich fürchte, dass der Alte Gott Euch im Auge behalt'n wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[54441] = { id = 54441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bluttor einnehmen", description = "Wir haben unsere Truppen in ganz Nazmir verteilt, doch wir müssen etwas tun, das Rastakhan zum Handeln zwingt.\n\nWir müssen höchstpersönlich nach Zuldazar einmarschieren und das Bluttor einnehmen. Dann werden sie uns ihre gesamte Armee entgegenwerfen.\n\nWie Ihr seht, sind wir die Einzigen, die noch übrig sind und das Bluttor angreifen können.\n\nShaw und Telaamon werden zurückbleiben, um den Vormarsch der restlichen Armee zu unterstützen.\n\nWir zwei werden die Schlachtbestie gemeinsam in das Bluttor reiten und es gewaltsam erobern.", sourceObjective = "Reitet die Schlachtbestie und besiegt die Zandalariarmee am Bluttor.", completion = "Ausgezeichnet. Wir haben die Zahl der Zandalari an der Frontlinie dezimiert und einen Weg für unsere Soldaten bereitet, auf dem sie einmarschieren können.\n\nEs wird Zeit, dass wir unseren Hauptangriff starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54442] = { id = 54442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestienzähmer Watteck" }
quests[54447] = { id = 54447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zwielichtige Gestalt", description = "Eure Anhänger sprechen von einem Schmuggler mit Witz und Verstand, der sie mit Geschichten von weit entfernten Ländern verzaubern konnte.\n\nObwohl es ein beträchtliches Sümmchen kostete, konnten sie ein Abzeichen erwerben. Wenn man dieses dem Schmuggler vorlegt, darf man Waren von ihm kaufen.", sourceObjective = "Bringt das Abzeichen zu der zwielichtigen Gestalt.", progress = "Glaubt Ihr wirklich, Ihr solltet mit mir sprechen?", completion = "Also schön, es scheint, als ob Ihr in Ordnung seid.\n\nJa, ich habe Haustiere, aber an die kommt man nicht so einfach ran, also erwartet nicht, dass ich sie verschenke.", sourceObjectiveStatus = "unverified-source-field" }
quests[54448] = { id = 54448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementares Azerit" }
quests[54449] = { id = 54449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementares Azerit" }
quests[54451] = { id = 54451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchersachen", description = "Wir Tortollaner wissen all die Hilfe zu schätzen, die Ihr uns habt zukommen lassen.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjective = "Sprecht mit Sammler Kojo.", completion = "Wir Tortollaner wissen all die Hilfe zu schätzen, die Ihr uns habt zukommen lassen.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54453] = { id = 54453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von Magni", description = "Champion von Azeroth, ich bin für all Eure Hilfe äußerst dankbar.\n\nBitte nehmt diese Vorräte als Zeichen meiner Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr weiterhin helft.", sourceObjective = "Sprecht mit Magni Bronzebart in Silithus, um Eure Belohnung zu erhalten.", completion = "Champion von Azeroth, ich bin für all Eure Hilfe äußerst dankbar.\n\nBitte nehmt diese Vorräte als Zeichen meiner Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr weiterhin helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54454] = { id = 54454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der 7. Legion", description = "{name}, dank Eures Kampfes gegen die Horde konnten unsere Truppen weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nWenn Ihr das Schlachtfeld weiter beherrscht, können unsere Truppen mehr Ressourcen erübrigen.", sourceObjective = "Sprecht mit Verteidigerin Jaelaana im Hafen von Boralus im Tiragardesund.", completion = "{name}, dank Eures Kampfes gegen die Horde konnten unsere Truppen weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nWenn Ihr das Schlachtfeld weiter beherrscht, können unsere Truppen mehr Ressourcen erübrigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54455] = { id = 54455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eidgebundenen", description = "{name}, dank Eures Kampfes gegen die Allianz konnten unsere Truppen weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nWenn Ihr das Schlachtfeld weiter beherrscht, können unsere Truppen mehr Ressourcen erübrigen.", sourceObjective = "Sprecht mit Ransa Graufeder im Hafen von Zandalar, um Eure Belohnung zu erhalten.", completion = "Meisterjäger, dank Eures Kampfes gegen die Allianz konnten unsere Truppen weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nWenn Ihr das Schlachtfeld weiter beherrscht, können unsere Truppen mehr Ressourcen erübrigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54456] = { id = 54456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte des Glutordens", description = "Der Glutorden weiß all die Hilfe zu schätzen, die Ihr uns habt zukommen lassen.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjective = "Sprecht mit Rüstmeister Alcorn in Aroms Wehr in Drustvar.", completion = "Der Glutorden weiß all die Hilfe zu schätzen, die Ihr uns habt zukommen lassen.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54457] = { id = 54457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Sturmwacht", description = "Wir wissen all die Hilfe zu schätzen, die Ihr uns habt zukommen lassen. Mögen die Gezeiten über Euch wachen.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjective = "Sprecht mit Schwester Liliana in Brennadam im Sturmsangtal.", completion = "Wir wissen all die Hilfe zu schätzen, die Ihr uns habt zukommen lassen. Mögen die Gezeiten über Euch wachen.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54458] = { id = 54458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Prachtmeeradmiralität", description = "Die Prachtmeeradmiralität weiß all die Hilfe zu schätzen, die Ihr uns habt zukommen lassen.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjective = "Sprecht mit Versorgerin Frauke im Hafen von Boralus, um Eure Belohnung zu erhalten.", completion = "Die Prachtmeeradmiralität weiß all die Hilfe zu schätzen, die Ihr uns habt zukommen lassen.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54459] = { id = 54459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der im Licht wandelt", description = "Shaw berichtet, dass Zandalarispäher ausgesandt wurden, um vor unserem \"großen Sturmangriff\" zu warnen. \n\nWir haben es geschafft, {name}. Die Horde und die Zandalari werden ihre Armeen unseren Streitkräften in Nazmir entgegenwerfen.\n\nWir können nicht zulassen, dass deren Opfer umsonst ist. Wir müssen nach Boralus zurück und Halford Bescheid sagen, dass es Zeit ist, zuzuschlagen.\n\nKommt, ich erschaffe ein Portal, durch das wir aufbrechen können, nachdem wir ein letztes Mal mit Telaamon gesprochen haben.", sourceObjective = "Kehrt zu Halford Wyrmbann in Boralus zurück.", completion = "Telaamons Opfer wird nicht vergessen werden, doch jetzt müssen wir los.", sourceObjectiveStatus = "unverified-source-field" }
quests[54460] = { id = 54460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von Talanjis Expedition", description = "Danke, Mann, die Expedition is' für all die Hilfe dankbar, die Ihr uns habt zukomm' lass'n.\n\nNehmt diese Vorräte als Zeichen unsrer Dankbarkeit und als 'n Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiter helft.", sourceObjective = "Sprecht mit Versorgerin Lija in den Ruinen von Zul'jan, um Eure Belohnung zu erhalten.", completion = "Danke, Mann, die Expedition is' für all die Hilfe dankbar, die Ihr uns habt zukomm' lass'n.\n\nNehmt diese Vorräte als Zeichen unsrer Dankbarkeit und als 'n Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiter helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54461] = { id = 54461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Voldunai", description = "Danke für Eure Hilfe in Vol'dun, {class}.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr weiterhin helft.", sourceObjective = "Sprecht mit Horterin Jena im Vulperaversteck, um Eure Belohnung zu erhalten.", completion = "Danke für Eure Hilfe in Vol'dun, {class}.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr weiterhin helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54462] = { id = 54462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte des Zandalariimperiums", description = "Das Zandalariimperium is' für all Eure Hilfe dankbar.\n\nBitte nehmt diese Vorräte als Zeichen von unsrer Dankbarkeit und als 'n Versprechen, dass es noch mehr davon gibt, wenn Ihr weiter helft.", sourceObjective = "Sprecht mit Natal'hakata in Dazar'alor, um Eure Belohnung zu erhalten.", completion = "Das Zandalariimperium is' für all Eure Hilfe dankbar.\n\nBitte nehmt diese Vorräte als Zeichen von unsrer Dankbarkeit und als 'n Versprechen, dass es noch mehr davon gibt, wenn Ihr weiter helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54463] = { id = 54463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemistische Gleichungen", sourceObjective = "Hey, {name}. Ich hab ein paar neue Rezepte erstellt, die ich Euch gern zeigen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[54464] = { id = 54464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemistische Gleichungen", sourceObjective = "{name}, schön Euch zu sehen. Ich hab an ein paar neuen Rezepten gearbeitet, die Ihr bestimmt gerne ausprobieren möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[54465] = { id = 54465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekunstpläne", sourceObjective = "Hey, {name}. Ich hab ein paar neue Pläne für Euch, falls Ihr interessiert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[54466] = { id = 54466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekunstpläne", sourceObjective = "Hallöchen, {name}. Ich hätt' da 'n paar neue Pläne für Euch. Wollt Ihr mal 'n Blick drauf werf'n?", sourceObjectiveStatus = "unverified-source-field" }
quests[54467] = { id = 54467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörtes Erbe" }
quests[54468] = { id = 54468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nalaess Federsucher" }
quests[54469] = { id = 54469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frische Gerichte", sourceObjective = "Ahoi, {name}. Ich hab ein paar neue Rezepte, frisch aus der Kombüse. Möchtet Ihr sie mal ausprobieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[54470] = { id = 54470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frische Gerichte", sourceObjective = "Willkommen zurück, {name}. Ich hab ein bisschen mit neuen Zutaten experimentiert und ein paar interessante Gerichte gezaubert.\n\nWollt Ihr mal einen Blick drauf werfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[54471] = { id = 54471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflege für die Verwundeten" }
