quests[54473] = { id = 54473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Formeln", sourceObjective = "Hey, {name}. Ich hab ein paar neue Formeln für Euch, falls Ihr interessiert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[54474] = { id = 54474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Formeln", sourceObjective = "Hallo, {name}. Was für eine nette Überraschung.\n\nIch habe ein paar neue verzauberte Formeln entwickelt, die Euch interessieren könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54475] = { id = 54475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technische Baupläne", sourceObjective = "Ahoi, {name}. Ich habe an ein paar neuen Plänen getüftelt, die Euch vielleicht interessieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[54476] = { id = 54476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technische Baupläne", sourceObjective = "Oh, {name}, Ihr werdet nicht glauben, woran ich gerade arbeite!\n\nMit diesem neuen Entwurf zwingen wir die Allianz in die Knie!", sourceObjectiveStatus = "unverified-source-field" }
quests[54477] = { id = 54477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelehrte Methoden", sourceObjective = "Hey, {name}. Ich war ziemlich produktiv in letzter Zeit. Wollt Ihr sehen, woran ich gearbeitet habe?", sourceObjectiveStatus = "unverified-source-field" }
quests[54478] = { id = 54478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelehrte Methoden", sourceObjective = "Schön, Euch wiederzusehen, {name}. Ich habe an ein paar neuen Rezepten gearbeitet. Wollt Ihr sie sehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[54479] = { id = 54479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzende Vorlagen", sourceObjective = "Willkommen zurück, {name}. Ich hab ein paar wundervolle neue Vorlagen, die ich Euch zeigen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[54480] = { id = 54480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzende Vorlagen", sourceObjective = "Willkommen zurück, {name}. Ihr müsst einen Blick auf meine neuen Vorlagen werfen, wenn Ihr Zeit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54481] = { id = 54481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ledrige Muster", sourceObjective = "Hey, {name}. Ich hab ein paar neue Muster für Euch, falls Ihr interessiert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[54482] = { id = 54482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ledrige Muster", sourceObjective = "Hey, {name}. Ich hab ein paar neue Muster für Euch, falls Ihr interessiert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[54483] = { id = 54483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maßgeschneiderte Ausbildung", sourceObjective = "Na, Sonnenschein, schön Euch zu sehen!\n\nWisst Ihr, was Eure Stimmung noch weiter aufhellen wird? Neue Rezepte! Schaut Euch an, was ich hier für Euch habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[54484] = { id = 54484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maßgeschneiderte Ausbildung", sourceObjective = "{name}, ich freue mich Euch zu sehen. Ich hab ein paar neue Muster für Euch, falls Ihr Zeit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54485] = { id = 54485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht von Dazar'alor", description = "Unsere Seestreitkräfte sind bereit, nach Zuldazar zu segeln. Bis wir dort ankommen, sollten sich die Truppen der Horde und der Zandalari in Nazmir befinden.\n\nKeeshan und Kelsey haben die Bomben überprüft, die im Hafen von Zuldazar platziert wurden. Diese sind scharf und warten nur darauf, die Zandalariflotte zu vernichten.\n\nRuft Eure Verbündeten zusammen und macht Euch bereit, nach Zuldazar zu segeln. \n\nWir werden die Zandalari vernichtend schlagen und den mächtigsten Verbündeten der Horde aus diesem Krieg entfernen.", sourceObjective = "Besiegt König Rastakhan in der Schlacht von Dazar'alor.", completion = "Wir haben einen Sieg errungen, der uns teuer zu stehen gekommen ist. Mekkadrill ist tot und in einem Gerät seines Mechs eingefroren.\n\nLady Jaina wird von unseren besten Heilern versorgt. Sie ist schwer verwundet, wird aber wohl überleben.\n\nWas Telaamon angeht... unsere Späher haben seine zerfetzte Leiche gefunden. Alle nach Nazmir entsendeten Soldaten wurden bis auf den letzten Mann getötet.\n\nAber wir haben es geschafft. Die Zandalariflotte ist dezimiert und König Rastakhan ist tot.\n\nUnser Krieg gegen die Horde ist so gut wie beendet. König Anduin wünscht, uns baldmöglichst zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54488] = { id = 54488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'aki der Kopfjäger" }
quests[54494] = { id = 54494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseren Einfluss ausweiten", description = "Während wir die Kriegsanstrengungen auf dem feindlichen Kontinent ausweiten, finden wir ideale Standorte für neue Außenposten und sogar Ausbaumöglichkeiten für unsere bestehenden.\n\nWenn sie einmal gesichert sind, werden diese Außenposten es uns ermöglichen, ein neues Flugnetzwerk nutzbar zu machen, mit dem wir das Gebiet schnell und sicher durchqueren können.", sourceObjective = "Sprecht mit Ransa Graufeder.", completion = "Bei mir könnt ihre zahlreiche Späherberichte und Außenpostenausbauten erwerben. Damit könnt Ihr neue Außenposten, Flugrouten und Ausbauten auf beiden Kontinenten freischalten. \n\nWenn Ihr Euch für einen Späherbereicht oder Außenpostenausbau entschieden habt, benutzt Euren Missionsbefehlstisch und weist Eure Truppen an, die Mission abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54495] = { id = 54495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseren Einfluss ausweiten", description = "Während wir die Kriegsanstrengungen auf dem feindlichen Kontinent ausweiten, finden wir ideale Standorte für neue Außenposten und sogar Ausbaumöglichkeiten für unsere bestehenden.\n\nWenn sie einmal gesichert sind, werden diese Außenposten es uns ermöglichen, ein neues Flugnetzwerk nutzbar zu machen, mit dem wir das Gebiet schnell und sicher durchqueren können.", sourceObjective = "Sprecht mit Verteidigerin Jaelaana.", completion = "Bei mir könnt ihre zahlreiche Späherberichte und Außenpostenausbauten erwerben. Damit könnt Ihr neue Außenposten, Flugrouten und Ausbauten auf beiden Kontinenten freischalten. \n\nWenn Ihr Euch für einen Späherbereicht oder Außenpostenausbau entschieden habt, benutzt Euren Missionsbefehlstisch und weist Eure Truppen an, die Mission abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
