quests[54509] = { id = 54509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitze des Dreizacks" }
quests[54510] = { id = 54510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missetat begangen", description = "Danke, dass Ihr dieses Artefakt zu uns zurückgebracht habt, {name}. Jetzt, da wir das Abyssische Szepter haben, kann die Flotte vorrücken, ohne Angst haben zu müssen, dass die Meere sich gegen uns wenden.\n\nBitte meldet unseren Erfolg Hochkommandant Wyrmbann.", sourceObjective = "Erstattet Hochkommandant Wyrmbann in Boralus Bericht.", completion = "Ausgezeichnet! Wir waren sehr besorgt darüber, dass sich das Abyssische Szepter in den Händen der Horde befand. Jetzt, da wir es geborgen haben, können wir nicht nur unsere endgültigen Pläne vorantreiben, wir haben auch unsere Freundschaft zu Kul Tiras erneut gestärkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54511] = { id = 54511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Todeshauptmännern!" }
quests[54512] = { id = 54512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigende Flut" }
