quests[54516] = { id = 54516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kisten klauben" }
quests[54518] = { id = 54518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeppelinzäsur", description = "Die Hordezeppeline haben sich hier für unsere Truppen als problematisch erwiesen. Ich habe versucht, auf die Schnelle etwas zu konstruieren, aber der Waffe fehlte trotz ihrer Wucht die nötige Reichweite, um die Zeppeline auszuschalten.\n\nDie Lordadmiralin hat uns eine nützliche Lösung für dieses Problem verschafft!\n\nSetzt diese behelfsmäßige Handkanone gegen die Zeppeline ein. Eine impulsartige Applizierung konzentrierter Thermalenergie wird einen Hitzeschock und kritisches Versagen auslösen!\n\nOder einfach ausgedrückt: Jagt sie in die Luft, solange sie außer Gefecht sind!", sourceObjective = "Zerstört die Hordezeppeline in der Angelpunktwerft.", progress = "Wenn Ihr diese Zeppeline ausschalten könntet, bevor sie auftauen und außer Reichweite fliegen, wäre uns der Sieg gewiss!", completion = "Ha! Jetzt sind die Luftstreitkräfte der Horde nicht mehr so überlegen, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[54519] = { id = 54519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouille in Bredouille", description = "Mein Patrouillentrupp hat die Horde aufgehalten, um Sturmherz und mir die Flucht zu ermöglichen. Ich muss hier bei der Lordadmiralin bleiben, also kann ich nicht selbst nach ihnen suchen. Mit etwas Glück sind sie noch da draußen und kämpfen tapfer weiter, während sie auf Verstärkung warten.\n\nNun, wir sind hier, um bei ihrer Rettung zu helfen. Könnt Ihr den Rest meines Patrouillentrupps für mich finden?", sourceObjective = "Findet die Mitglieder von Taelias Patrouillentrupp.", completion = "Als die Horde auftauchte, haben sie wie Sturmtakler gekämpft. Hart wie Stahl aus Kul Tiras, jeder Einzelne von ihnen.\n\nIch werde veranlassen, dass die Verletzten beschützt werden, bis wir den Rückzug antreten können. Die Diensttauglichen werde ich mit Waffen versorgen.\n\nIch nehme stark an, dass sie die Horde für ihren Verlust bluten lassen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54520] = { id = 54520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesengte Schösslinge" }
quests[54521] = { id = 54521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Hexerei" }
