quests[54559] = { id = 54559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit Hakenschnabel!", description = "Ein außergewöhnlich brutaler Halunke, der die Ausbreitung der Pestilenz entlang der Werft überwachte, hat Hakenschnabel eingefangen.\n\nRosalinde kann unsere Waffen nicht ohne mein mechanisches Fachwissen reparieren, also könntet Ihr vielleicht mein armes Hakenschnäbelchen befreien und den teuflischen Ritter töten, der es quält?", sourceObjective = "Besiegt Maurizio Todesrausch und befreit Hakenschnabel.", completion = "Ich kann Euch für die rechtzeitige Rettung meines Greifen gar nicht genug danken. Ich bin Euch auch unendlich dankbar, dass Ihr das teuflische Monster beseitigt habt, das mein armes Tierchen gequält hat.", sourceObjectiveStatus = "unverified-source-field" }
