quests[54574] = { id = 54574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'tago" }
quests[54576] = { id = 54576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeregans Beste", description = "Die Anführer der Allianz haben sich darauf geeinigt, eine Eliteeinheit der Gnomenluftwaffe zu finanzieren.\n\nUnd Ihr wurdet ausgewählt, die Testgruppe der Fliegenden Luftunterstützungsgarde anzuführen. Ich habe einige der besten Tüftler und Soldaten Gnomeregans zusammengestellt, die jetzt unter Eurem Kommando stehen.\n\nDie drei befinden sich bereits hier in Neu-Tüftlerstadt. Stellt Euch ihnen vor und ruft sie zusammen.", sourceObjective = "Sprecht mit den drei Mitgliedern der F.L.U.G.-Truppe.", completion = "Es ist Zeit, Euch ins Bild zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54577] = { id = 54577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Hallen und verstaubte Zahnräder", description = "Eliteflieger wären nichts ohne die letzten Innovationen der Flugmaschinentechnologie.\n\nEs gibt da nur ein kleines Problem.\n\nWir mussten den innovativen neuen Motor, den wir gebaut haben, bei der Evakuierung Gnomeregans zurücklassen. Wir brauchen diesen Prototyp, wenn die Bomber gefahrlos abheben sollen!", sourceObjective = "Findet den arkanen Maschinenprototyp in den Ingenieurslaboren von Gnomeregan.", completion = "Ausgezeichnet! Ich habe Tüftelbogen und Autoknall schon vorausgeschickt, damit sie den Motor für den Einbau bereitmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54578] = { id = 54578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweigfürst Aldrus" }
quests[54579] = { id = 54579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gnom hinter dem Trogg", sourceObjective = "Helft Tüftelbogen, die Maschine zum Laufen zu bringen.", progress = "Ja?", completion = "Gebt mir nur eine Sekunde, den Ursprung des Signals zurückzuverfolgen...", sourceObjectiveStatus = "unverified-source-field" }
quests[54580] = { id = 54580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dilemma in der Tundra", description = "Während Ihr in Gnomeregan wart, haben wir ein Notsignal von der Landebahn Kurbelzisch in der Boreanischen Tundra erhalten. Das dürfte die perfekte Gelegenheit sein, zu zeigen, wozu F.L.U.G. imstande ist!\n\nIch habe den Rest Eurer Truppe bereits vorausgeschickt. Trefft Euch dort mit ihnen.", sourceObjective = "Sprecht mit Getriebehauptmann Winkelfeder auf der Landebahn Kurbelzisch in der Boreanischen Tundra.", completion = "Oh, Kommandant! Wir sind kurz vor Euch eingetroffen. Die Piloten hier haben gerade die Situation erläutert.", sourceObjectiveStatus = "unverified-source-field" }
quests[54581] = { id = 54581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und jetzt zu mechanischerem Federvieh", description = "Die Gnome hier berichten, dass Troggs aus dem Norden hergekommen sind und alles und jeden angegriffen haben.\n\nJetzt fällt uns die Aufgabe zu, diese Situation zu bereinigen! Und zum Glück habe ich dafür den perfekten Plan. Wir müssen die Waffe des Bombers kalibrieren. Es ist weit weniger riskant, das auf dem Boden zu tun, als es in der Luft zu versuchen.\n\nDann mal los, <Kommandant/Kommandantin>!", sourceObjective = "Tötet 10 Schläger oder Schrottschmeißer der Eisenfressertroggs.", sourceObjectiveStatus = "unverified-source-field" }
quests[54582] = { id = 54582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlauer als der Durchschnittstrogg", description = "<Getriebehauptmann Winkelfeders Stimme erwacht über Euer persönliches Kommunikationssystem zum Leben.>\n\nEine Aufklärungspilotin hat einen Spähflug über die Station absolviert. Sie hat gemeldet, dass sich offenbar ein Trogg auf der obersten Ebene aufhält, der größer und schlauer ist als die anderen. Irgendwie hat er es geschafft, einen Beschützo-Panz der Station für seine Zwecke umzufunktionieren.\n\nBringt ihn zur Strecke!", sourceObjective = "Tötet Krugg den Schlauen.", progress = "Habt Ihr etwas herausgefunden?", completion = "Der große Trogg hatte das hier bei sich? Ich glaube, ich habe eine Idee...", sourceObjectiveStatus = "unverified-source-field" }
quests[54583] = { id = 54583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennender Goliath" }
