quests[54609] = { id = 54609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrichterin Drakara" }
quests[54610] = { id = 54610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der tortollanischen Sucher", description = "Eure Verbündeten unter den tortollanischen Suchern haben Eure Anwesenheit erbeten. Sie möchten Euch für Eure unermüdliche Unterstützung eine Belohnung überreichen.", sourceObjective = "Sprecht mit Sammler Kojo.", sourceObjectiveStatus = "unverified-source-field" }
quests[54611] = { id = 54611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Champions von Azeroth", description = "Magni Bronzebart hat voller Dank Eure Anwesenheit erbeten. Er möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit Magni Bronzebart in Silithus, um Eure Belohnung zu erhalten.", completion = "Seid gegrüßt, Hochlord.\n\nSchon seit geraumer Zeit leistet Ihr Azeroth treue Dienste. Meine Dankbarkeit dafür lässt sich kaum in Worte fassen.\n\nBitte nehmt also diese Trophäen als Zeichen meiner Dankbarkeit. Je mehr Ihr Azeroth helft, desto mehr kann ich Euch überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54612] = { id = 54612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut und Asche" }
quests[54613] = { id = 54613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelt verbannt hält besser", description = "Im ganzen Hochland reißen sich Elementare aller Art von ihren Bindungen los.\n\nSchickt sie zurück in das urzeitliche Chaos, aus dem sie gekommen sind.", sourceObjective = "Tötet 12 brennende, schäumende, rumpelnde oder donnernde Verbannte oder Wächter im Arathihochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[54614] = { id = 54614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exorzismus durchführen", description = "Selbst im Tod trachten diese Narren der Allianz immer noch nach Hordenterritorium.\n\nVertreibt ihre rachsüchtigen Geister aus den Ruinen von Burg Stromgarde, bevor ihre Verderbnis um sich greift.", sourceObjective = "Tötet 12 rachsüchtige Geister in Burg Stromgarde.", sourceObjectiveStatus = "unverified-source-field" }
quests[54615] = { id = 54615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bund wird verlieren", description = "Selbst nach dem Fall von Burg Stromgarde setzt der Bund von Arathor seinen Einsatz im Hochland fort.\n\nDas nördliche Farmland wird zur Horde gehören. Geht und vernichtet diese Menschen.", sourceObjective = "Tötet 12 Mitglieder des Bunds von Arathor auf dem Bauernhof der Dabyries.", sourceObjectiveStatus = "unverified-source-field" }
quests[54616] = { id = 54616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faust um Faust", description = "Wenn sich die Oger der Felsfäuste nicht der Horde anschließen wollen, gibt es keinen Platz für sie in Arathi.\n\nIhr wisst, was getan werden muss.", sourceObjective = "Tötet 12 Oger der Felsfäuste im Arathihochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[54617] = { id = 54617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden des Syndikats", description = "Als wäre der Bund von Arathor nicht schon schlimm genug, fallen immer noch Agenten des Syndikats aus dem Alteracgebirge ein und vertreiben die ehrlichen Hilfsarbeiter der Horde.\n\nBestraft sie.", sourceObjective = "Tötet 12 Mitglieder des Syndikats auf Go'Sheks Hof.", sourceObjectiveStatus = "unverified-source-field" }
quests[54618] = { id = 54618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der 7. Legion", description = "Die Kommandanten der 7. Legion haben Eure Anwesenheit erbeten. Man möchte Euch für Euren außergewöhnlichen Einsatz eine Belohnung überreichen.", sourceObjective = "Sprecht mit Verteidigerin Jaelaana im Hafen von Boralus im Tiragardesund.", completion = "Meisterjäger, dank Eures Kampfes gegen die Horde konnten unsere Truppen weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nWenn Ihr das Schlachtfeld weiter beherrscht, können unsere Truppen mehr Ressourcen erübrigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54619] = { id = 54619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleichborken beseitigen", description = "Der blutrünstige Bleichborkenklan hat sich immer geweigert, der Horde beizutreten... Und jetzt, wo die Horde Arathi hält, werden wir erreichen, wozu die Allianz nicht imstande war.\n\nVertreibt die Waldtrolle aus dem Hochland.", sourceObjective = "Tötet 12 Trolle der Bleichborken im Arathihochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[54620] = { id = 54620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Entweihten", description = "Selbst nach der Zerstörung von Unterstadt kämpfen die Entweihten immer noch gegen unsere Präsenz im Arathihochland.\n\nDas Farmland von Go'Shek wird wieder zur Allianz gehören. Geht und besiegt die Verlassenen.", sourceObjective = "Tötet 12 Entweihte auf Go'Sheks Hof.", sourceObjectiveStatus = "unverified-source-field" }
quests[54621] = { id = 54621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelt verbannt hält besser", description = "Im ganzen Hochland reißen sich Elementare aller Art von ihren Bindungen los.\n\nSchickt sie zurück in das urzeitliche Chaos, aus dem sie gekommen sind.", sourceObjective = "Tötet 12 brennende, schäumende, rumpelnde oder donnernde Verbannte oder Wächter im Arathihochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[54622] = { id = 54622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exorzismus durchführen", description = "Selbst im Tod trachten diese Narren der Horde immer noch nach Allianzterritorium.\n\nVertreibt ihre rachsüchtigen Geister aus den Ruinen von Ar'gorok, bevor ihre Verderbnis um sich greift.", sourceObjective = "Tötet 12 rachsüchtige Geister in Ar'gorok.", sourceObjectiveStatus = "unverified-source-field" }
quests[54623] = { id = 54623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faust um Faust", description = "Die Oger der Felsfäuste setzen Arathi schon seit dem Zweiten Krieg zu. Es hört einfach nicht auf.\n\nIhr wisst, was getan werden muss.", sourceObjective = "Tötet 12 Oger der Felsfäuste im Arathihochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[54624] = { id = 54624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden des Syndikats", description = "Als wären die Entweihten nicht schon schlimm genug, fallen immer noch Agenten des Syndikats aus dem Alteracgebirge ein und vertreiben die ehrlichen Bauern der Allianz.\n\nBestraft sie.", sourceObjective = "Tötet 12 Mitglieder des Syndikats auf dem Bauernhof der Dabyries.", sourceObjectiveStatus = "unverified-source-field" }
quests[54625] = { id = 54625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleichborken beseitigen", description = "Die Geschichte des Bleichborkenklans im Hochland von Arathi ist lang und blutig.\n\nZeigt ihnen, wie viel blutiger sie noch werden kann.", sourceObjective = "Tötet 12 Trolle der Bleichborken im Arathihochland.", sourceObjectiveStatus = "unverified-source-field" }
quests[54626] = { id = 54626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Eidgebundenen", description = "Die Kommandanten der Eidgebundenen haben Eure Anwesenheit erbeten. Man möchte Euch für Euren außergewöhnlichen Einsatz eine Belohnung überreichen.", sourceObjective = "Sprecht mit Ransa Graufeder im Hafen von Zandalar, um Eure Belohnung zu erhalten.", completion = "Hochlord, dank Eures Kampfes gegen die Allianz konnten unsere Truppen weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nWenn Ihr das Schlachtfeld weiter beherrscht, können unsere Truppen mehr Ressourcen erübrigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54627] = { id = 54627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Glutordens", description = "Eure Verbündeten im Glutorden haben Eure Anwesenheit erbeten. Sie möchten Euch für Eure unermüdliche Unterstützung eine Belohnung überreichen.", sourceObjective = "Sprecht mit Rüstmeister Alcorn in Aroms Wehr in Drustvar.", sourceObjectiveStatus = "unverified-source-field" }
quests[54628] = { id = 54628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Sturmwacht", description = "Die dankbaren Truppen der Sturmwacht haben Eure Anwesenheit erbeten. Sie möchten Euch für Eure unermüdliche Unterstützung eine Belohnung überreichen.", sourceObjective = "Sprecht mit Schwester Liliana in Brennadam im Sturmsangtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[54629] = { id = 54629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Prachtmeeradmiralität", description = "Die dankbaren Anführer der Prachtmeeradmiralität haben Eure Anwesenheit erbeten. Man möchte Euch für Eure unermüdliche Unterstützung des Hauses Prachtmeer eine Belohnung überreichen.", sourceObjective = "Sprecht mit Versorgerin Frauke im Hafen von Boralus, um Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54630] = { id = 54630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion von Talanjis Expedition", description = "Eure Verbündeten in Talanjis Expedition haben Eure Anwesenheit erbeten. Sie möchten Euch für Eure unermüdliche Unterstützung eine Belohnung überreichen.", sourceObjective = "Sprecht mit Versorgerin Lija in den Ruinen von Zul'jan, um Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54631] = { id = 54631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Voldunai", description = "Eure Verbündeten unter den Voldunai haben Eure Anwesenheit erbeten. Sie möchten Euch für Eure unermüdliche Unterstützung eine Belohnung überreichen.", sourceObjective = "Sprecht mit Horterin Jena im Vulperaversteck, um Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54632] = { id = 54632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Zandalariimperiums", description = "Die dankbaren Anführer des Zandalariimperiums haben Eure Anwesenheit erbeten. Man möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit Natal'hakata in Dazar'alor, um Eure Belohnung zu erhalten.", completion = "Grüße, Todesgebieter.\n\nSchon seit 'ner ganz'n Weile helft Ihr dem Zandalariimperium, wo Ihr nur könnt. Unsre Dankbarkeit dafür kann ich kaum ausdrück'n.\n\nAlso nehmt diese Trophäen als Dank für Eure Hilfe an. Je mehr Ihr uns helft, desto mehr könn' wir Euch geb'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54635] = { id = 54635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mekkadrills Schlachtpläne", description = "Wir haben also fast alles, was wir brauchen... bis auf die Position dieses Luftschiffs!\n\nAber meine Kumpels von der Versicherung haben herausgebracht, wo diese heißen Infos zu finden sind.\n\nBesorgt mir Mekkadrills Schlachtpläne, damit wir endlich mit dem RICHTIG lustigen Teil loslegen können!", sourceObjective = "Findet Mekkadrills Schlachtpläne.", progress = "Habt Ihr mir den Kram schon besorgt?", completion = "Das ist perfekt! Dann wollen wir diese nervige Nulpe mal in die Luft jagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54636] = { id = 54636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandbinder Sodir" }
quests[54638] = { id = 54638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trommelschlägerei" }
quests[54639] = { id = 54639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Signal vom Sturmgipfel", description = "Es sieht so aus, als ob das Signal vom Sturmgipfel gesendet wird.\n\nZeit, diese Flugmaschinen zum Einsatz zu bringen! Ich werde das Signal von unterwegs weiterverfolgen, um eine genauere Messung zu bekommen.", sourceObjective = "Fliegt mit Eurer Einheit zum Sturmgipfel.", completion = "Ich habe eine Tarnvorrichtung vorbereitet, die unseren aktuellen Aufenthaltsort verbergen wird. Wir sollten im Moment sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[54640] = { id = 54640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomen est Omen", description = "Wir müssen Tüftelbogen Deckung geben, während sie unsere neue Flugroute austüftelt.\n\n<Der Getriebehauptmann übergibt Euch einen Miniaturspinnenpanzer.>\n\nEr mag wenig beeindruckend aussehen, aber das hier ist ein voll funktionsfähiger Spinnenpanzer. Ihr müsst ihn nur entschrumpfen. Benutzt ihn, um die Troggs da unten zu dezimieren, um sie abzulenken.", sourceObjective = "Entschrumpft den Angriffspanzer und tötet damit Troggs.", progress = "Gebt den Troggs einen Grund zur Sorge!", completion = "Ich bin froh, dass Ihr sicher hier angekommen seid, Kommandant!", sourceObjectiveStatus = "unverified-source-field" }
quests[54641] = { id = 54641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Gnomeregan!", sourceObjective = "Betretet die Hallen des Steins und besiegt Telzo Funkenschraub.", progress = "Funkenschraub muss besiegt werden, zum Wohle der Gnomheit.", completion = "Geht es allen gut? Unser Tüftler kann einen Sanitäterbot bereitstellen, wenn nötig.", sourceObjectiveStatus = "unverified-source-field" }
quests[54642] = { id = 54642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "F.L.U.G.-bereit", description = "Das war knapp, aber wir haben es geschafft, Funkenschraub zu besiegen! Die Gnomheit und Azeroth wurden vor einer Bedrohung gerettet, die sie nicht einmal kannten.\n\nDas ist hoffentlich das letzte Mal, dass wir von Thermadrahts alten Schlägern hören.\n\nWir sollten zu Hauptmann Funkdüse zurückkehren. Er wird bestimmt einen vollständigen Bericht haben wollen.", sourceObjective = "Kehrt zu Hauptmann Tret Funkdüse in Neu-Tüftlerstadt zurück.", completion = "Soldat, stillgestanden!", sourceObjectiveStatus = "unverified-source-field" }
quests[54643] = { id = 54643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evezon der Ewige" }
quests[54644] = { id = 54644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerittransport" }
quests[54645] = { id = 54645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Erde" }
quests[54646] = { id = 54646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmarschall Furon" }
quests[54647] = { id = 54647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bierische Absichten" }
quests[54648] = { id = 54648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückstrom der Kaldorei" }
quests[54649] = { id = 54649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammen des Krieges" }
quests[54650] = { id = 54650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muk'luk" }
quests[54652] = { id = 54652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegskasse", description = "Willkommen an der Kriegsfront, {name}. Es freut mich, dass Ihr auf unserer Seite kämpft.\n\nDas Wichtigste zuerst: Wir müssen Ressourcen sammeln, um unsere Kontrolle über Bashal'Aran zu festigen und um unsere Truppen zu stärken.\n\nAlle von uns gesammelten Ressourcen landen in der Kriegskasse. Schaut Euch den Inhalt an und seht, was Ihr davon brauchen könnt.", sourceObjective = "Beschafft Ressourcen aus der Kriegskasse in Bashal'Aran.", completion = "Gut. Jetzt können wir zur Sache kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54654] = { id = 54654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine explosive Situation", description = "Wir haben zwar einige Eisenvorräte, es könnten aber deutlich mehr sein.\n\nBegebt Euch zur Mine bei den Ruinen von Lornesta, erobert sie von den jetzigen Besetzern zurück und sorgt dafür, dass diese Goblins ihre Arbeit machen können.\n\nWenn Ihr ihnen etwas ausreichend Zerstörerisches gebt, sollte das seinen Zweck erfüllen.", sourceObjective = "Versorgt Goblinextraktoren in der Lornestamine mit Sprengstoff.", progress = "Wir brauchen mehr Eisen, wenn wir diese Schlacht gewinnen wollen!", completion = "Das nenn ich explosive Produktivität. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[54655] = { id = 54655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Holzweg", description = "Wir werden mehr Holz brauchen, wenn wir Bashal'Aran zu einer richtigen Festung ausbauen wollen.\n\nIn den Vorräten, die wir zu diesem Zweck mitgebracht haben, befindet sich auch eine Axt. Schnappt sie Euch und schaut, wie Ihr Euch damit nützlich machen könnt, um die Basis neu aufzubauen.", sourceObjective = "Nehmt Euch eine robuste Axt und sammelt 5 Scheite frisch gespaltenes Holz vom nahe gelegenen Finsterwaldholz.", progress = "Wir brauchen das Holz, um unsere Ziele hier zu erreichen.", completion = "Habe ich da gerade frisches Sägemehl gerochen? Dieses Holz wird uns beim Ausbau unserer Stellung hier ein gutes Stück weiterbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54656] = { id = 54656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekruten der Dunkelküste", description = "Ohne eine angemessene Truppenstärke können wir unmöglich gewinnen.\n\nZunächst einmal müssen wir die Kaserne wieder aufbauen, damit Signe ihre Arbeit machen kann. Signe ist eine der Val'kyr der Dunklen Fürstin und kann Streitkräfte für uns erwecken.\n\nWenn die Kaserne wieder aufgebaut ist, sprecht mit Signe und rekrutiert einen Trupp. Die Soldaten können bestimmt eine Menge lernen, indem sie an Eurer Seite kämpfen.", sourceObjective = "Baut die Kaserne wieder auf und sprecht danach mit Signe, um einen Verbündeten zu rekrutieren.", completion = "Manche dieser Rekruten sind etwas... frischer... als andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[54657] = { id = 54657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen und Rüstungen", description = "Keifer weiß, dass Trupps Waffen brauchen. Und Rüstungen. Rüstungen und Waffen.\n\nKeifer will, dass Archibald Rüstungen und Waffen für Trupps herstellt. Hört auf Keifer und sprecht mit Archibald.", sourceObjective = "Sprecht mit Archibald, um zu erfahren, was das Arsenal zu bieten hat.", progress = "Wir sind zwar weit von Unterstadt entfernt, doch genau hier gehöre ich hin.", completion = "Keifer will schicke neue Rüstungen und Waffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54658] = { id = 54658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar der Stürme", description = "Der Altar der Stürme wurde wieder aufgebaut. Sehr einzigartig, dieser Altar. Genau wie Goblins.\n\nKeifer ist erfreut. Keifer möchte über diese Art von Macht gebieten.\n\nHört auf Keifer und sprecht mit dem Knirps Mizzyk. Der sagt Euch, was der Altar kann.", sourceObjective = "Sprecht mit Mizzyk, um zu erfahren, was der Altar der Stürme zu bieten hat.", completion = "Keifer weiß, dass Ihr mit dieser großen Macht verantwortungsvolle Dinge bewerkstelligen werdet.\n\nKeifer weiß es genau.", sourceObjectiveStatus = "unverified-source-field" }
quests[54659] = { id = 54659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Alchemist für alle Fälle", description = "Nachdem wir die Dunkelküste erobert hatten, richteten wir am Düsterseestrand ein Alchemielabor ein, um uns die latenten Kräfte dieses Gebiets zunutze zu machen.\n\nLeider lief nicht alles nach Plan, und die Allianz überrannte das Labor.\n\nKönntet Ihr das Gebiet zurückerobern und dann mit Professor Seuchenherd sprechen, um herauszufinden, wie er Euch weiterhelfen kann?", sourceObjective = "Nehmt den Düsterseestrand ein und sprecht dann mit Professor Seuchenherd, um herauszufinden, was er zu bieten hat.", progress = "Habt Ihr am Düsterseestrand etwas gefunden?", completion = "Wir Apotheker verstehen unser Handwerk, das könnt Ihr mir glauben. Wir haben unzählige Abhandlungen darüber verfasst, was man mit nur wenigen Pfund Fleisch anstellen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[54660] = { id = 54660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuche in der Luft", description = "Wir brauchen mehr Feuerkraft, und die Goblins sind in dieser Hinsicht wirklich sehr hilfsbereit, nicht wahr? Vor allem Zarvik hat seine Kunst seit unserer Eroberung der Dunkelküste weiter verfeinert.\n\nWieso sprecht Ihr nicht mit ihm und findet heraus, was er da in der Werkstatt auf die Beine stellt?", sourceObjective = "Sprecht mit Zarvik Bummfix, um zu erfahren, was die Werkstatt zu bieten hat.", completion = "Mit diesen Seuchenkatapulten werden wir die Urtume bestimmt im Handumdrehen in die Knie zwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54661] = { id = 54661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echolotung", description = "Gut, dass Ihr hier seid. Diese Fledermäuse müssen in die Luft und uns von oben unterstützen.\n\nIch habe einen Entwurf eines Flugplans für die Dunkelküste. Unser Vorteil ist, dass die Fledermäuse im Dunkeln sehen können, wozu die meisten von uns nicht imstande sind.\n\nSprecht mit Avery, und sie wird dafür sorgen, dass Ihr sicher nach Bashal'Aran zurückgelangt.", sourceObjective = "Bringt Kurbelknalls Notiz zu Eurem Kommandanten in Bashal'Aran.", completion = "Hervorragende Arbeit. Diese Fledermäuse werden uns helfen, den Kampf um die Lufthoheit zu gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
