quests[54681] = { id = 54681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritkarawane" }
quests[54682] = { id = 54682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verschwundene Klinge", description = "<Das Echo der Klinge Xal'atath schwebt noch vor Euch. Das Bewusstsein, das sich zuvor in dem Dolch befunden hatte, ist zwar verschwunden, aber an seiner statt lässt sich immer noch große Macht wahrnehmen.\n\nIhr spürt, dass die Waffe jetzt mit einer anderen Stimme spricht und einem anderen Zweck dient...\n\nIhr fühlt Euch angehalten, den König zu warnen, dass die Klinge sich jetzt in den Händen des Feindes befinden könnte.>", sourceObjective = "Berichtet König Anduin von der Abwesenheit von Xal'atath.", completion = "<Ihr erzählt Anduin von Xal'atath und N'Zoth. Seine Miene verfinstert sich.>\n\nDas sind düstere Neuigkeiten, Champion.\n\nDie Allianz steht kurz vor dem Sieg. Wenn die Bansheekönigin von einer neuen Waffe erfahren haben sollte, wird sie den Krieg für alle Zeiten fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54683] = { id = 54683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarze Klinge", description = "<Die einstmals Xal'atath genannte Klinge liegt vor Euch auf dem Boden. Das Bewusstsein, das sich zuvor in dem Dolch befunden hatte, ist zwar verschwunden, aber in ihr lässt sich noch immer große Macht wahrnehmen.\n\nEs scheint, als würde die Waffe jetzt mit einer anderen Stimme sprechen und einem anderen Zweck dienen...\n\nIhr fühlt Euch angehalten, dieses Artefakt zum Kriegshäuptling zu bringen.>", sourceObjective = "Bringt den Dolch zu Kriegshäuptling Sylvanas Windläufer.", completion = "<Als Ihr Sylvanas den Dolch präsentiert, umspielt ein vages Lächeln ihre Lippen. Für einen kurzen Moment scheinen sich ihre Augen zu verdunkeln. Zweifellos nur eine optische Täuschung.>\n\nWieder einmal habt Ihr Euch als wahrer Champion erwiesen, {name}. Diese Klinge wird der Kompass sein, der uns zum Sieg führt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54684] = { id = 54684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanist Quintril" }
